-- =============================================================================
-- Migration 0070: K.0 B t/m K.2 B — aanvullen tot 8 vragen per soort
-- =============================================================================
-- Gegenereerd door scripts/k-aanvullen-8.ts — niet met de hand bewerken.
--
-- Elk cluster van K.0 B t/m K.2 B had zes vragen. Deze migratie voegt
-- er twee aan toe, zodat een leerling niet steeds dezelfde som terugziet.
-- k0b_bepaald_exact had er al acht en blijft buiten deze migratie.
--
-- De controle verwacht ná deze migratie acht vragen per cluster. De
-- stappencontrole telt alleen de nieuwe opgaven, niet de stappen die er
-- al stonden.
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 15 topics, 32 clusters
--   • 64 vragen met elk 4 stappen (256 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k0b_standaardprimitieven', $ksql$Standaardprimitieven$ksql$, 1, 'primitiveren'),
  ('k0b_lineaire_kern', $ksql$De regel voor f(ax + b)$ksql$, 2, 'primitiveren'),
  ('k1a_kern_herkennen', $ksql$De kern herkennen$ksql$, 4, 'primitiveren'),
  ('k1a_primitiveren_ketting', $ksql$Primitiveren met de omgekeerde kettingregel$ksql$, 5, 'primitiveren'),
  ('k1a_toepassingen', $ksql$Oppervlakte en inhoud met de omgekeerde kettingregel$ksql$, 6, 'toepassingen'),
  ('k1b_gonio', $ksql$Gonio primitiveren met de substitutiemethode$ksql$, 7, 'primitiveren'),
  ('k1b_bepaald', $ksql$Bepaalde integralen met de substitutiemethode$ksql$, 8, 'integralen'),
  ('k1b_toepassingen', $ksql$Oppervlakte met de substitutiemethode$ksql$, 9, 'toepassingen'),
  ('k2a_partieel', $ksql$Primitiveren met partieel integreren$ksql$, 10, 'primitiveren'),
  ('k2a_bepaald', $ksql$Bepaalde integralen met partieel integreren$ksql$, 11, 'integralen'),
  ('k2a_toepassingen', $ksql$Oppervlakte met partieel integreren$ksql$, 12, 'toepassingen'),
  ('k2b_herhaald', $ksql$Twee keer partieel integreren$ksql$, 13, 'primitiveren'),
  ('k2b_bepaald', $ksql$Bepaalde integralen met herhaald partieel integreren$ksql$, 14, 'integralen'),
  ('k2b_toepassingen', $ksql$Oppervlakte met herhaald partieel integreren$ksql$, 15, 'toepassingen'),
  ('k2b_logaritme', $ksql$Herhaald partieel integreren met een macht van ln$ksql$, 16, 'primitiveren')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

