  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bepaalde integralen met e-machten en logaritmen$ksql$, 2),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Oppervlakte en p bepalen$ksql$, 1),
