  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(3x)$$ksql$, $ksql$-x cos(3x)/3 + sin(3x)/9 + c$ksql$, $ksql$F(x) = -\tfrac{1}{3}x\cos(3x) + \tfrac{1}{9}\sin(3x) + c$ksql$, 2, 7, ARRAY[$ksql$-(1/3) x cos(3x) + (1/9) sin(3x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (3x + 2)\cos(2x)$$ksql$, $ksql$(3x + 2) sin(2x)/2 + 3 cos(2x)/4 + c$ksql$, $ksql$F(x) = \tfrac{1}{2}(3x + 2)\sin(2x) + \tfrac{3}{4}\cos(2x) + c$ksql$, 3, 8, ARRAY[$ksql$1/2 (3x + 2) sin(2x) + 3/4 cos(2x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{4x}$$ksql$, $ksql$(4x - 1) e^(4x) / 16 + c$ksql$, $ksql$F(x) = \tfrac{1}{16}(4x - 1)\mathrm{e}^{4x} + c$ksql$, 2, 7, ARRAY[$ksql$x e^(4x)/4 - e^(4x)/16 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x - 3)\mathrm{e}^{-x}$$ksql$, $ksql$(1 - 2x) e^(-x) + c$ksql$, $ksql$F(x) = (1 - 2x)\mathrm{e}^{-x} + c$ksql$, 3, 8, ARRAY[$ksql$(1 - 2x)/e^x + c$ksql$, $ksql$-(2x - 1) e^(-x) + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{3}\ln(x)$$ksql$, $ksql$x^4 ln(x)/4 - x^4/16 + c$ksql$, $ksql$F(x) = \tfrac{1}{4}x^{4}\ln(x) - \tfrac{1}{16}x^{4} + c$ksql$, 2, 7, ARRAY[$ksql$(1/4) x^4 ln(x) - (1/16) x^4 + c$ksql$]::text[]),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{2}}$$ksql$, $ksql$-(ln(x) + 1)/x + c$ksql$, $ksql$F(x) = -\dfrac{\ln(x) + 1}{x} + c$ksql$, 3, 8, ARRAY[$ksql$-ln(x)/x - 1/x + c$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} x\sin(x)\,\mathrm{d}x$$ksql$, $ksql$sqrt(3)/2 - pi/6$ksql$, $ksql$\dfrac{\sqrt{3}}{2} - \dfrac{1}{6}\pi$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, $ksql$1/4$ksql$, $ksql$\tfrac{1}{4}$ksql$, 3, 8, ARRAY[$ksql$0,25$ksql$]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, $ksql$(e^2 + 1)/4$ksql$, $ksql$\dfrac{\mathrm{e}^{2} + 1}{4}$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x^{2}\ln(x)\,\mathrm{d}x$$ksql$, $ksql$(2e^3 + 1)/9$ksql$, $ksql$\dfrac{2\mathrm{e}^{3} + 1}{9}$ksql$, 3, 8, ARRAY[]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$1 - 2/e$ksql$, $ksql$1 - \dfrac{2}{\mathrm{e}}$ksql$, 2, 7, ARRAY[$ksql$(e - 2)/e$ksql$]::text[]),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $1 - \dfrac{3}{\mathrm{e}^{2}}$. Bereken exact $p$.$ksql$, $ksql$p = 2$ksql$, $ksql$p = 2$ksql$, 3, 8, ARRAY[$ksql$2$ksql$]::text[]),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(2x)$$ksql$, $ksql$x^2 sin(2x)/2 + x cos(2x)/2 - sin(2x)/4 + c$ksql$, $ksql$F(x) = \tfrac{1}{2}x^{2}\sin(2x) + \tfrac{1}{2}x\cos(2x) - \tfrac{1}{4}\sin(2x) + c$ksql$, 2, 7, ARRAY[$ksql$(1/2) x^2 sin(2x) + (1/2) x cos(2x) - (1/4) sin(2x) + c$ksql$]::text[]),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = (x^{2} + x)\sin(x)$$ksql$, $ksql$-(x^2 + x) cos(x) + (2x + 1) sin(x) + 2 cos(x) + c$ksql$, $ksql$F(x) = -(x^{2} + x)\cos(x) + (2x + 1)\sin(x) + 2\cos(x) + c$ksql$, 3, 8, ARRAY[]::text[]),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{3x}$$ksql$, $ksql$(9x^2 - 6x + 2) e^(3x) / 27 + c$ksql$, $ksql$F(x) = \dfrac{9x^{2} - 6x + 2}{27}\,\mathrm{e}^{3x} + c$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = (x^{2} - 2)\mathrm{e}^{-2x}$$ksql$, $ksql$-(2x^2 + 2x - 3) e^(-2x) / 4 + c$ksql$, $ksql$F(x) = -\dfrac{2x^{2} + 2x - 3}{4}\,\mathrm{e}^{-2x} + c$ksql$, 3, 8, ARRAY[$ksql$(3 - 2x - 2x^2) e^(-2x) / 4 + c$ksql$]::text[]),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\cos(x)$$ksql$, $ksql$e^(2x) (2 cos(x) + sin(x)) / 5 + c$ksql$, $ksql$F(x) = \tfrac{1}{5}\mathrm{e}^{2x}\big(2\cos(x) + \sin(x)\big) + c$ksql$, 2, 7, ARRAY[$ksql$(1/5) e^(2x) (2 cos(x) + sin(x)) + c$ksql$]::text[]),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-2x}\cos(3x)$$ksql$, $ksql$e^(-2x) (-2 cos(3x) + 3 sin(3x)) / 13 + c$ksql$, $ksql$F(x) = \dfrac{\mathrm{e}^{-2x}\big(-2\cos(3x) + 3\sin(3x)\big)}{13} + c$ksql$, 3, 8, ARRAY[]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{3x}\,\mathrm{d}x$$ksql$, $ksql$(5e^3 - 2)/27$ksql$, $ksql$\dfrac{5\mathrm{e}^{3} - 2}{27}$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(2x)\,\mathrm{d}x$$ksql$, $ksql$-pi/4$ksql$, $ksql$-\dfrac{1}{4}\pi$ksql$, 3, 8, ARRAY[]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x$$ksql$, $ksql$(e^pi - 2)/5$ksql$, $ksql$\dfrac{\mathrm{e}^{\pi} - 2}{5}$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{-2x}\cos(3x)\,\mathrm{d}x$$ksql$, $ksql$(2 - 3 e^(-pi)) / 13$ksql$, $ksql$\dfrac{2 - 3\mathrm{e}^{-\pi}}{13}$ksql$, 3, 8, ARRAY[$ksql$(2 - 3/e^pi)/13$ksql$]::text[]),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x^{2} + 1)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$2e - 3$ksql$, $ksql$2\mathrm{e} - 3$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = x^{2}\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $2\mathrm{e}^{2} - 2$. Bereken exact $p$.$ksql$, $ksql$p = 2$ksql$, $ksql$p = 2$ksql$, 3, 8, ARRAY[$ksql$2$ksql$]::text[]),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = 2\ln^{2}(x)$$ksql$, $ksql$2x ln(x)^2 - 4x ln(x) + 4x + c$ksql$, $ksql$F(x) = 2x\ln^{2}(x) - 4x\ln(x) + 4x + c$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln^{2}(x)}{x^{3}}$$ksql$, $ksql$-(2 ln(x)^2 + 2 ln(x) + 1)/(4x^2) + c$ksql$, $ksql$F(x) = -\dfrac{2\ln^{2}(x) + 2\ln(x) + 1}{4x^{2}} + c$ksql$, 3, 8, ARRAY[]::text[]),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x\ln^{2}(x)\,\mathrm{d}x$$ksql$, $ksql$(e^2 - 1)/4$ksql$, $ksql$\dfrac{\mathrm{e}^{2} - 1}{4}$ksql$, 2, 7, ARRAY[]::text[]),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln^{2}(x)$, de $x$-as en de lijn $x = \mathrm{e}^{3}$. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$5e^3 - 2$ksql$, $ksql$5\mathrm{e}^{3} - 2$ksql$, 3, 8, ARRAY[]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = 4x^{3} - \cos(x)$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Twee losse termen met een min ertussen: primitiveer elke term apart.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = 4x^{3} - \cos(x)$ksql$, 1, $ksql$De termen zijn $4x^{3}$ en $-\cos(x)$. Herschrijven is niet nodig.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = 4x^{3} - \cos(x)$ksql$, 2, $ksql$$4x^{3}$ geeft $4 \cdot \tfrac{1}{4}x^{4} = x^{4}$. En $\cos(x)$ geeft $\sin(x)$, dus $-\cos(x)$ geeft $-\sin(x)$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = 4x^{3} - \cos(x)$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = x^{4} - \sin(x) + c$. Controle: differentieer $F$ en je krijgt $4x^{3} - \cos(x)$ terug.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = \dfrac{x^{2} + 2}{x^{3}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een breuk met één term in de noemer: deel eerst uit. Er is geen quotiëntregel voor primitiveren.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = \dfrac{x^{2} + 2}{x^{3}}$ksql$, 1, $ksql$Deel uit: $f(x) = \dfrac{x^{2}}{x^{3}} + \dfrac{2}{x^{3}} = x^{-1} + 2x^{-3}$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = \dfrac{x^{2} + 2}{x^{3}}$ksql$, 2, $ksql$$x^{-1}$ is geen gewone macht: de machtsregel geldt niet voor $n = -1$, dus die term geeft $\ln(x)$. En $2x^{-3}$ geeft $2 \cdot \dfrac{1}{-2}x^{-2} = -x^{-2} = -\dfrac{1}{x^{2}}$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_machten_gonio', $ksql$f(x) = \dfrac{x^{2} + 2}{x^{3}}$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \ln(x) - \dfrac{1}{x^{2}} + c$. Controle: differentieer $F$ en je krijgt $\dfrac{1}{x} + \dfrac{2}{x^{3}} = \dfrac{x^{2} + 2}{x^{3}}$ terug.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = 4 \cdot 5^{x}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Eén term: een constante maal een exponentiële functie $g^{x}$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = 4 \cdot 5^{x}$ksql$, 1, $ksql$Herschrijven is niet nodig. Het grondtal is $5$, de factor ervoor is $4$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = 4 \cdot 5^{x}$ksql$, 2, $ksql$$g^{x}$ geeft $\dfrac{g^{x}}{\ln(g)}$. Dus $5^{x}$ geeft $\dfrac{5^{x}}{\ln(5)}$, en de factor $4$ blijft ervoor staan.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = 4 \cdot 5^{x}$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \dfrac{4 \cdot 5^{x}}{\ln(5)} + c$. Controle: differentieer $F$; de afgeleide van $5^{x}$ is $5^{x}\ln(5)$, en die $\ln(5)$ valt weg tegen de noemer.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = \dfrac{(3^{x} + 2^{x})^{2}}{6^{x}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een breuk van exponentiële functies: werk het kwadraat uit en deel term voor term door $6^{x}$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = \dfrac{(3^{x} + 2^{x})^{2}}{6^{x}}$ksql$, 1, $ksql$$(3^{x} + 2^{x})^{2} = 3^{2x} + 2 \cdot 3^{x} \cdot 2^{x} + 2^{2x}$. Omdat $6^{x} = 2^{x} \cdot 3^{x}$ wordt de breuk $\left(\dfrac{3}{2}\right)^{x} + 2 + \left(\dfrac{2}{3}\right)^{x}$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = \dfrac{(3^{x} + 2^{x})^{2}}{6^{x}}$ksql$, 2, $ksql$Elke $g^{x}$ geeft $\dfrac{g^{x}}{\ln(g)}$, en de constante $2$ geeft $2x$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_exponenten', $ksql$f(x) = \dfrac{(3^{x} + 2^{x})^{2}}{6^{x}}$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \dfrac{\left(\frac{3}{2}\right)^{x}}{\ln\left(\frac{3}{2}\right)} + 2x + \dfrac{\left(\frac{2}{3}\right)^{x}}{\ln\left(\frac{2}{3}\right)} + c$. Controle: differentieer term voor term en je krijgt de drie termen van de uitgedeelde breuk terug.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = \ln(4x^{3})$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een logaritme van een macht van $x$. Je mag hem eerst uit elkaar trekken, of meteen de vorm $xln(ldots) - ldots$ gebruiken.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = \ln(4x^{3})$ksql$, 1, $ksql$$\ln(4x^{3}) = \ln(4) + 3\ln(x)$. De constante $\ln(4)$ primitiveer je straks als $\ln(4) \cdot x$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = \ln(4x^{3})$ksql$, 2, $ksql$$\ln(x)$ geeft $x\ln(x) - x$, dus $3\ln(x)$ geeft $3x\ln(x) - 3x$. Tel daarbij $x\ln(4)$ op: dat is precies $x\ln(4x^{3}) - 3x$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = \ln(4x^{3})$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = x\ln(4x^{3}) - 3x + c$. Controle: differentieer $F$ en je krijgt $\ln(4x^{3}) + x \cdot \dfrac{3}{x} - 3 = \ln(4x^{3})$ terug.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = 3 \cdot \log(5x)$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een logaritme met grondtal 10. Die schrijf je eerst om naar $ln$, want daar is de primitieve van bekend.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = 3 \cdot \log(5x)$ksql$, 1, $ksql$$\log(5x) = \dfrac{\ln(5x)}{\ln(10)}$, dus $f(x) = \dfrac{3}{\ln(10)}\ln(5x)$.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = 3 \cdot \log(5x)$ksql$, 2, $ksql$$\ln(5x)$ geeft $x\ln(5x) - x$. De factor $\dfrac{3}{\ln(10)}$ blijft ervoor staan.$ksql$),
  ('k0b_standaardprimitieven', 'k0b_logaritmen', $ksql$f(x) = 3 \cdot \log(5x)$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \dfrac{3\big(x\ln(5x) - x\big)}{\ln(10)} + c$. Controle: differentieer de haakjes tot $\ln(5x)$ en deel door $\ln(10)$; dat is weer $3\log(5x)$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = \sin(5x - 1)$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. In $f$ zit een kern $ax + b$, dus de primitieven van $f(ax + b)$ zijn $\dfrac{1}{a}F(ax + b) + c$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = \sin(5x - 1)$ksql$, 1, $ksql$Buitenkant $\sin$, kern $5x - 1$. Dus $a = 5$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = \sin(5x - 1)$ksql$, 2, $ksql$Primitiveer alleen de buitenkant, met de kern erin: $\sin$ geeft $-\cos$, dus $-\cos(5x - 1)$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = \sin(5x - 1)$ksql$, 3, $ksql$Deel door $a = 5$: $F(x) = -\tfrac{1}{5}\cos(5x - 1) + c$. Controle: de kettingregel geeft de factor $5$ weer terug, en $5 \cdot -\tfrac{1}{5} = -1$ wordt $+\sin(5x - 1)$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = 4\sin(1 - 3x) + e^{4x}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Twee losse termen, elk met een eigen lineaire kern. Primitiveer ze apart met de regel $\dfrac{1}{a}F(ax + b)$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = 4\sin(1 - 3x) + e^{4x}$ksql$, 1, $ksql$Eerste term: buitenkant $\sin$, kern $1 - 3x$, dus $a = -3$. Tweede term: buitenkant $e^{\ldots}$, kern $4x$, dus $a = 4$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = 4\sin(1 - 3x) + e^{4x}$ksql$, 2, $ksql$$\sin$ geeft $-\cos$. Delen door $a = -3$ draait het minteken om: $\dfrac{4}{-3} \cdot (-\cos(1 - 3x)) = \dfrac{4}{3}\cos(1 - 3x)$. En $e^{4x}$ geeft $\dfrac{1}{4}e^{4x}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_e_gonio', $ksql$f(x) = 4\sin(1 - 3x) + e^{4x}$ksql$, 3, $ksql$Schrijf het antwoord op: $F(x) = \tfrac{4}{3}\cos(1 - 3x) + \tfrac{1}{4}e^{4x} + c$. Controle: differentieer; de kettingregel op de eerste term geeft $\tfrac{4}{3} \cdot (-\sin(1 - 3x)) \cdot (-3) = 4\sin(1 - 3x)$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = (2x + 1)^{3}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een macht van een lineaire kern. De primitieven van $(ax + b)^{n}$ zijn $\dfrac{1}{a} cdot \dfrac{1}{n + 1}(ax + b)^{n + 1} + c$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = (2x + 1)^{3}$ksql$, 1, $ksql$Buitenkant $(\ldots)^{3}$, kern $2x + 1$. Dus $a = 2$ en $n = 3$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = (2x + 1)^{3}$ksql$, 2, $ksql$Primitiveer de buitenkant: $(\ldots)^{3}$ geeft $\dfrac{1}{4}(2x + 1)^{4}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = (2x + 1)^{3}$ksql$, 3, $ksql$Deel door $a = 2$: $F(x) = \tfrac{1}{8}(2x + 1)^{4} + c$. Controle: differentieer en de kettingregel geeft $\tfrac{1}{8} \cdot 4(2x + 1)^{3} \cdot 2 = (2x + 1)^{3}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = \dfrac{5}{(1 - 4x)^{2}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Schrijf de breuk als een macht: $\dfrac{5}{(1 - 4x)^{2}} = 5(1 - 4x)^{-2}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = \dfrac{5}{(1 - 4x)^{2}}$ksql$, 1, $ksql$Buitenkant $(\ldots)^{-2}$, kern $1 - 4x$. Dus $a = -4$ en $n = -2$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = \dfrac{5}{(1 - 4x)^{2}}$ksql$, 2, $ksql$Primitiveer de buitenkant: $5(1 - 4x)^{-2}$ geeft $5 \cdot \dfrac{1}{-1}(1 - 4x)^{-1} = -\dfrac{5}{1 - 4x}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_breuk_wortel', $ksql$f(x) = \dfrac{5}{(1 - 4x)^{2}}$ksql$, 3, $ksql$Deel door $a = -4$: het minteken valt weg en $F(x) = \dfrac{5}{4(1 - 4x)} + c$. Controle: differentieer en je krijgt $\dfrac{5}{4} \cdot \dfrac{4}{(1 - 4x)^{2}} = \dfrac{5}{(1 - 4x)^{2}}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = 3^{4x + 1}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een exponentiële functie met een lineaire kern. Eerst de buitenkant $g^{x}$ primitiveren, daarna delen door $a$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = 3^{4x + 1}$ksql$, 1, $ksql$Buitenkant $3^{\ldots}$, kern $4x + 1$. Dus $a = 4$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = 3^{4x + 1}$ksql$, 2, $ksql$De primitieve van $3^{t}$ is $\dfrac{3^{t}}{\ln(3)}$. Met de kern erin: $\dfrac{3^{4x + 1}}{\ln(3)}$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = 3^{4x + 1}$ksql$, 3, $ksql$Deel door $a = 4$: $F(x) = \dfrac{3^{4x + 1}}{4\ln(3)} + c$. Controle: de kettingregel brengt een factor $4\ln(3)$ terug, die tegen de noemer wegvalt.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = \ln(5 - 2x)$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Een $\ln$ van een lineaire kern. De primitieve van $\ln(t)$ is $t\ln(t) - t$; daarna deel je door $a$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = \ln(5 - 2x)$ksql$, 1, $ksql$Buitenkant $\\ln$, kern $5 - 2x$. Dus $a = -2$. Let op: $a$ is negatief.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = \ln(5 - 2x)$ksql$, 2, $ksql$Primitiveer de buitenkant met de kern erin: $(5 - 2x)\\ln(5 - 2x) - (5 - 2x)$.$ksql$),
  ('k0b_lineaire_kern', 'k0b_lin_exp_ln', $ksql$f(x) = \ln(5 - 2x)$ksql$, 3, $ksql$Deel door $a = -2$: $F(x) = -\\tfrac{1}{2}\\big((5 - 2x)\\ln(5 - 2x) - (5 - 2x)\\big) + c$. Controle: de kettingregel geeft een factor $-2$, en $-\\tfrac{1}{2} \\cdot (-2) = 1$, dus je houdt $\\ln(5 - 2x)$ over.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $8x(x^{2} + 3)^{3}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $8x(x^{2} + 3)^{3}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 1, $ksql$Vóór de $\\mathrm{d}x$ staat een macht van de kern $x^{2} + 3$, met de factor $8x$ ervoor. De afgeleide van de kern is $2x$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $8x(x^{2} + 3)^{3}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 2, $ksql$$8x = 4 \cdot 2x$, dus $8x\,\mathrm{d}x = 4\,\mathrm{d}(x^{2} + 3)$. Dan is $\int 4g^{3}\,\mathrm{d}g = g^{4}$, met $g = x^{2} + 3$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $8x(x^{2} + 3)^{3}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 3, $ksql$Op de puntjes staat $(x^{2} + 3)^{4}$: $8x(x^{2} + 3)^{3}\,\mathrm{d}x = \mathrm{d}\big((x^{2} + 3)^{4}\big)$. Controle: differentieer en je krijgt $4(x^{2} + 3)^{3} \cdot 2x = 8x(x^{2} + 3)^{3}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(x)\,\mathrm{e}^{\sin(x)}\,\mathrm{d}x = \mathrm{d}(\ldots + 5)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(x)\,\mathrm{e}^{\sin(x)}\,\mathrm{d}x = \mathrm{d}(\ldots + 5)$$ksql$, 1, $ksql$Vóór de $\\mathrm{d}x$ staat een e-macht met kern $\\sin(x)$. De afgeleide van die kern is $\\cos(x)$, en die staat er precies bij.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(x)\,\mathrm{e}^{\sin(x)}\,\mathrm{d}x = \mathrm{d}(\ldots + 5)$$ksql$, 2, $ksql$Dus $\\cos(x)\\,\\mathrm{d}x = \\mathrm{d}(\\sin(x))$ en $\\int \\mathrm{e}^{g}\\,\\mathrm{d}g = \\mathrm{e}^{g}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(x)\,\mathrm{e}^{\sin(x)}\,\mathrm{d}x = \mathrm{d}(\ldots + 5)$$ksql$, 3, $ksql$Op de puntjes staat $\\mathrm{e}^{\\sin(x)}$: $\\cos(x)\\,\\mathrm{e}^{\\sin(x)}\\,\\mathrm{d}x = \\mathrm{d}\\big(\\mathrm{e}^{\\sin(x)} + 5\\big)$. De losse $5$ verandert de afgeleide niet.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (2x + a)\mathrm{e}^{x^{2} + 4x}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht met een kern, en ervóór een factor met $x$. Die factor moet een constante maal de afgeleide van de kern zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (2x + a)\mathrm{e}^{x^{2} + 4x}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 4x$, dus $g'(x) = 2x + 4$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (2x + a)\mathrm{e}^{x^{2} + 4x}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De factor is $2x + a$. Die moet gelijk zijn aan $2x + 4$, dus $a = 4$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (2x + a)\mathrm{e}^{x^{2} + 4x}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dan is $(2x + 4)\,\mathrm{d}x = \mathrm{d}(x^{2} + 4x)$ en $\int \mathrm{e}^{g}\,\mathrm{d}g = \mathrm{e}^{g}$. Dus $F(x) = \mathrm{e}^{x^{2} + 4x} + c$. Controle: differentiëren geeft $(2x + 4)\mathrm{e}^{x^{2} + 4x}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 3}{(x^{2} + 3x + 4)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een kwadraat van een kern in de noemer. De teller moet een constante maal de afgeleide van die kern zijn.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 3}{(x^{2} + 3x + 4)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 3x + 4$, dus $g'(x) = 2x + 3$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 3}{(x^{2} + 3x + 4)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De teller is $ax + 3$. Die valt samen met $2x + 3$ als $a = 2$. De constante ervoor is dan $1$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 3}{(x^{2} + 3x + 4)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dus $\int \dfrac{1}{g^{2}}\,\mathrm{d}g = \int g^{-2}\,\mathrm{d}g = -\dfrac{1}{g}$. Terugschrijven: $F(x) = -\dfrac{1}{x^{2} + 3x + 4} + c$. Controle: differentiëren geeft $\dfrac{2x + 3}{(x^{2} + 3x + 4)^{2}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 6x^{2}(x^{3} - 1)^{2}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 6x^{2}(x^{3} - 1)^{2}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{3} - 1$, dus $g'(x) = 3x^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 6x^{2}(x^{3} - 1)^{2}$ksql$, 2, $ksql$$6x^{2} = 2 \cdot 3x^{2}$, dus $6x^{2}\,\mathrm{d}x = 2\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 6x^{2}(x^{3} - 1)^{2}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int 2g^{2}\,\mathrm{d}g = \tfrac{2}{3}g^{3}$. Dus $F(x) = \tfrac{2}{3}(x^{3} - 1)^{3} + c$. Controle: differentiëren geeft $2(x^{3} - 1)^{2} \cdot 3x^{2} = 6x^{2}(x^{3} - 1)^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (2x - 4)(x^{2} - 4x + 1)^{6}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór precies de afgeleide van die kern.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (2x - 4)(x^{2} - 4x + 1)^{6}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} - 4x + 1$, dus $g'(x) = 2x - 4$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (2x - 4)(x^{2} - 4x + 1)^{6}$ksql$, 2, $ksql$De factor ervoor is precies $g'(x)$, dus $(2x - 4)\,\mathrm{d}x = \mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (2x - 4)(x^{2} - 4x + 1)^{6}$ksql$, 3, $ksql$Primitiveer: $\int g^{6}\,\mathrm{d}g = \tfrac{1}{7}g^{7}$. Dus $F(x) = \tfrac{1}{7}(x^{2} - 4x + 1)^{7} + c$. Controle: differentiëren geeft $(x^{2} - 4x + 1)^{6} \cdot (2x - 4)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x}{3x^{2} + 1}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een kern in de noemer. Is de teller de afgeleide van de noemer, dan komt er $\ln$ uit.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x}{3x^{2} + 1}$ksql$, 1, $ksql$Kies de kern: $g(x) = 3x^{2} + 1$, dus $g'(x) = 6x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x}{3x^{2} + 1}$ksql$, 2, $ksql$De teller is precies $g'(x)$, en $g(x)$ is altijd positief. Dus $\int \dfrac{1}{g}\,\mathrm{d}g = \ln(g)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x}{3x^{2} + 1}$ksql$, 3, $ksql$$F(x) = \ln(3x^{2} + 1) + c$. Controle: differentiëren geeft $\dfrac{6x}{3x^{2} + 1}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{2x^{2} + 5}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een wortel van een kern in de noemer. Schrijf de wortel als macht $-	frac{1}{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{2x^{2} + 5}}$ksql$, 1, $ksql$Kies de kern: $g(x) = 2x^{2} + 5$, dus $g'(x) = 4x$. Dan is $f(x) = x \cdot g^{-\frac{1}{2}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{2x^{2} + 5}}$ksql$, 2, $ksql$$x = \tfrac{1}{4} \cdot 4x$, dus $x\,\mathrm{d}x = \tfrac{1}{4}\,\mathrm{d}g$. De integraal wordt $\int \tfrac{1}{4} g^{-\frac{1}{2}}\,\mathrm{d}g = \tfrac{1}{4} \cdot 2g^{\frac{1}{2}} = \tfrac{1}{2}\sqrt{g}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{2x^{2} + 5}}$ksql$, 3, $ksql$$F(x) = \tfrac{1}{2}\sqrt{2x^{2} + 5} + c$. Controle: differentiëren geeft $\tfrac{1}{2} \cdot \tfrac{1}{2}(2x^{2} + 5)^{-\frac{1}{2}} \cdot 4x = \dfrac{x}{\sqrt{2x^{2} + 5}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\,\mathrm{e}^{\cos(x)}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht met een gonio als kern. Kijk of de factor ervoor de afgeleide van die kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\,\mathrm{e}^{\cos(x)}$ksql$, 1, $ksql$Kies de kern: $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\,\mathrm{e}^{\cos(x)}$ksql$, 2, $ksql$Er staat $\sin(x)$, dat is $-g'(x)$. Dus $\sin(x)\,\mathrm{d}x = -\mathrm{d}g$ en de integraal wordt $\int -e^{g}\,\mathrm{d}g = -e^{g}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\,\mathrm{e}^{\cos(x)}$ksql$, 3, $ksql$$F(x) = -\mathrm{e}^{\cos(x)} + c$. Controle: differentiëren geeft $-e^{\cos(x)} \cdot (-\sin(x)) = \sin(x)\,e^{\cos(x)}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \cos(x)\ln(\sin(x))$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een $\ln$ van een kern, met ervóór de afgeleide van die kern.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \cos(x)\ln(\sin(x))$ksql$, 1, $ksql$Kies de kern: $g(x) = \sin(x)$, dus $g'(x) = \cos(x)$. Op dit domein is $\sin(x) > 0$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \cos(x)\ln(\sin(x))$ksql$, 2, $ksql$$\cos(x)\,\mathrm{d}x = \mathrm{d}g$, dus de integraal wordt $\int \ln(g)\,\mathrm{d}g = g\ln(g) - g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \cos(x)\ln(\sin(x))$ksql$, 3, $ksql$$F(x) = \sin(x)\ln(\sin(x)) - \sin(x) + c$. Controle: differentiëren geeft $\cos(x)\ln(\sin(x)) + \cos(x) - \cos(x) = \cos(x)\ln(\sin(x))$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x^{2}(x^{3} + 1)^{2}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: op $[0, 1]$ ligt de grafiek op of boven de $x$-as, dus de oppervlakte is $\displaystyle\int_{0}^{1} 3x^{2}(x^{3} + 1)^{2}\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x^{2}(x^{3} + 1)^{2}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Deel 2, de kern: $g(x) = x^{3} + 1$, dus $g'(x) = 3x^{2}$. De factor ervoor is precies $g'(x)$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x^{2}(x^{3} + 1)^{2}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$$\int g^{2}\,\mathrm{d}g = \tfrac{1}{3}g^{3}$, dus een primitieve is $\tfrac{1}{3}(x^{3} + 1)^{3}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x^{2}(x^{3} + 1)^{2}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\left[\tfrac{1}{3}(x^{3} + 1)^{3}\right]_{0}^{1} = \tfrac{1}{3} \cdot 8 - \tfrac{1}{3} \cdot 1 = \tfrac{7}{3}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{3x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Deel 1: wentelen om de $x$-as geeft inhoud $\pi\int_{a}^{b}\big(f(x)\big)^{2}\,\mathrm{d}x$. Hier loopt $x$ van $0$ tot $1$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{3x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$Kwadrateer eerst: $\big(\sqrt{3x}\,\mathrm{e}^{x^{2}}\big)^{2} = 3x\,\mathrm{e}^{2x^{2}}$. De integraal wordt $\pi\int_{0}^{1} 3x\,\mathrm{e}^{2x^{2}}\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{3x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Deel 2: kern $g(x) = 2x^{2}$, dus $g'(x) = 4x$ en $3x = \tfrac{3}{4} \cdot 4x$. Primitiveren geeft $\int \tfrac{3}{4}e^{g}\,\mathrm{d}g = \tfrac{3}{4}e^{2x^{2}}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{3x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$Vul de grenzen in: $\pi\left[\tfrac{3}{4}e^{2x^{2}}\right]_{0}^{1} = \pi\left(\tfrac{3}{4}e^{2} - \tfrac{3}{4}\right) = \tfrac{3}{4}\pi\left(e^{2} - 1\right)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(3x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een tangens. Schrijf $\tan = \dfrac{\sin}{\cos}$ en kies de cosinus als kern.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(3x)$$ksql$, 1, $ksql$$\tan(3x) = \dfrac{\sin(3x)}{\cos(3x)}$. Kern $g(x) = \cos(3x)$, dus $g'(x) = -3\sin(3x)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(3x)$$ksql$, 2, $ksql$$\sin(3x)\,\mathrm{d}x = -\tfrac{1}{3}\,\mathrm{d}(\cos(3x))$, dus de integraal wordt $\int -\tfrac{1}{3} \cdot \dfrac{1}{g}\,\mathrm{d}g = -\tfrac{1}{3}\ln|g|$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \tan(3x)$$ksql$, 3, $ksql$$F(x) = -\tfrac{1}{3}\ln|\cos(3x)| + c$. Controle: differentiëren geeft $-\tfrac{1}{3} \cdot \dfrac{-3\sin(3x)}{\cos(3x)} = \tan(3x)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{3 + \sin(x)}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een sinus en een cosinus. De cosinus is de afgeleide van wat in de noemer staat.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{3 + \sin(x)}$$ksql$, 1, $ksql$Kies de kern: $g(x) = 3 + \sin(x)$, dus $g'(x) = \cos(x)$. Die noemer is altijd minstens $2$, dus positief.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{3 + \sin(x)}$$ksql$, 2, $ksql$$\cos(x)\,\mathrm{d}x = \mathrm{d}g$, dus $\int \dfrac{1}{g}\,\mathrm{d}g = \ln(g)$.$ksql$),
  ('k1b_gonio', 'k1b_tangens', $ksql$Primitiveer: $f(x) = \dfrac{\cos(x)}{3 + \sin(x)}$$ksql$, 3, $ksql$$F(x) = \ln(3 + \sin(x)) + c$. Controle: differentiëren geeft $\dfrac{\cos(x)}{3 + \sin(x)}$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een oneven macht van een sinus. Splits er één sinus af en herschrijf de rest met $\sin^{2} + \cos^{2} = 1$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)$$ksql$, 1, $ksql$$\sin^{3}(x) = \sin(x)\big(1 - \cos^{2}(x)\big)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)$$ksql$, 2, $ksql$Kern $g(x) = \cos(x)$, dus $\sin(x)\,\mathrm{d}x = -\mathrm{d}g$. De integraal wordt $\int -(1 - g^{2})\,\mathrm{d}g = -g + \tfrac{1}{3}g^{3}$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \sin^{3}(x)$$ksql$, 3, $ksql$$F(x) = -\cos(x) + \tfrac{1}{3}\cos^{3}(x) + c$. Controle: differentiëren geeft $\sin(x) - \cos^{2}(x)\sin(x) = \sin(x)\big(1 - \cos^{2}(x)\big) = \sin^{3}(x)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een oneven macht van een cosinus, met een lineaire kern in het argument.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(2x)$$ksql$, 1, $ksql$$\cos^{3}(2x) = \cos(2x)\big(1 - \sin^{2}(2x)\big)$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(2x)$$ksql$, 2, $ksql$Kern $g(x) = \sin(2x)$, dus $g'(x) = 2\cos(2x)$ en $\cos(2x)\,\mathrm{d}x = \tfrac{1}{2}\,\mathrm{d}g$. De integraal wordt $\int \tfrac{1}{2}(1 - g^{2})\,\mathrm{d}g = \tfrac{1}{2}g - \tfrac{1}{6}g^{3}$.$ksql$),
  ('k1b_gonio', 'k1b_oneven_macht', $ksql$Primitiveer: $f(x) = \cos^{3}(2x)$$ksql$, 3, $ksql$$F(x) = \tfrac{1}{2}\sin(2x) - \tfrac{1}{6}\sin^{3}(2x) + c$. Controle: differentiëren geeft $\cos(2x) - \tfrac{1}{2}\sin^{2}(2x)\cos(2x) = \cos(2x)\big(1 - \sin^{2}(2x)\big) = \cos^{3}(2x)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{6}\pi} \tan(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het is een bepaalde integraal. Schrijf $\tan(x) = \dfrac{\sin(x)}{\cos(x)}$ en primitiveer eerst.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{6}\pi} \tan(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kern $g(x) = \cos(x)$, dus $\sin(x)\,\mathrm{d}x = -\mathrm{d}(\cos(x))$. Een primitieve is $-\ln|\cos(x)|$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{6}\pi} \tan(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Bij $x = 0$ is $\cos(x) = 1$. Bij $x = \tfrac{1}{6}\pi$ is $\cos(x) = \tfrac{1}{2}\sqrt{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{6}\pi} \tan(x)\,\mathrm{d}x$$ksql$, 3, $ksql$$\left[-\ln(\cos(x))\right]_{0}^{\frac{1}{6}\pi} = -\ln\left(\tfrac{1}{2}\sqrt{3}\right) = \ln\left(\dfrac{2}{\sqrt{3}}\right) = \tfrac{1}{2}\ln\left(\dfrac{4}{3}\right)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{1 + \sin(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. De teller is de afgeleide van de noemer, dus dit wordt een $\ln$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{1 + \sin(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Kern $g(x) = 1 + \sin(x)$, dus $g'(x) = \cos(x)$. Een primitieve is $\ln(1 + \sin(x))$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{1 + \sin(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$Je kunt de grenzen ook meenemen in $g$: bij $x = 0$ hoort $g = 1$, bij $x = \tfrac{1}{2}\pi$ hoort $g = 2$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \dfrac{\cos(x)}{1 + \sin(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$$\left[\ln(1 + \sin(x))\right]_{0}^{\frac{1}{2}\pi} = \ln(2) - \ln(1) = \ln(2)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{3}{x\ln(x)}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal met $\ln$ in de noemer. De factor $\dfrac{1}{x}$ is de afgeleide van $\ln(x)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{3}{x\ln(x)}\,\mathrm{d}x$$ksql$, 1, $ksql$Kern $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$ en $\dfrac{1}{x}\,\mathrm{d}x = \mathrm{d}g$. Een primitieve is $3\ln|\ln(x)|$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{3}{x\ln(x)}\,\mathrm{d}x$$ksql$, 2, $ksql$Grenzen in $g$: bij $x = \mathrm{e}$ hoort $g = 1$, bij $x = \mathrm{e}^{2}$ hoort $g = 2$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{\mathrm{e}}^{\mathrm{e}^{2}} \dfrac{3}{x\ln(x)}\,\mathrm{d}x$$ksql$, 3, $ksql$$\left[3\ln(\ln(x))\right]_{\mathrm{e}}^{\mathrm{e}^{2}} = 3\ln(2) - 3\ln(1) = 3\ln(2)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 4x\,\mathrm{e}^{-2x^{2}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. Een e-macht met kern $-2x^{2}$, en ervóór een factor met $x$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 4x\,\mathrm{e}^{-2x^{2}}\,\mathrm{d}x$$ksql$, 1, $ksql$Kern $g(x) = -2x^{2}$, dus $g'(x) = -4x$. Er staat $4x = -g'(x)$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 4x\,\mathrm{e}^{-2x^{2}}\,\mathrm{d}x$$ksql$, 2, $ksql$Dus $4x\,\mathrm{d}x = -\mathrm{d}g$ en $\int -e^{g}\,\mathrm{d}g = -e^{g} = -e^{-2x^{2}}$.$ksql$),
  ('k1b_bepaald', 'k1b_grenzen_ln_e', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} 4x\,\mathrm{e}^{-2x^{2}}\,\mathrm{d}x$$ksql$, 3, $ksql$$\left[-e^{-2x^{2}}\right]_{0}^{1} = -e^{-2} - (-e^{0}) = 1 - \dfrac{1}{e^{2}}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 1} = g$: $\displaystyle\int_{0}^{8} \dfrac{x}{\sqrt{x + 1}}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van $x$ plus een getal, met ervóór een losse $x$. De afgeleide van wat onder de wortel staat is $1$, dus de omgekeerde kettingregel helpt niet. Stel $\sqrt{x + 1} = g$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 1} = g$: $\displaystyle\int_{0}^{8} \dfrac{x}{\sqrt{x + 1}}\,\mathrm{d}x$$ksql$, 1, $ksql$Dan is $x + 1 = g^{2}$, dus $x = g^{2} - 1$ en $\mathrm{d}x = 2g\,\mathrm{d}g$. Bij $x = 0$ hoort $g = 1$, bij $x = 8$ hoort $g = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 1} = g$: $\displaystyle\int_{0}^{8} \dfrac{x}{\sqrt{x + 1}}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int_{1}^{3} \dfrac{g^{2} - 1}{g} \cdot 2g\,\mathrm{d}g = \int_{1}^{3} (2g^{2} - 2)\,\mathrm{d}g = \left[\tfrac{2}{3}g^{3} - 2g\right]_{1}^{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 1} = g$: $\displaystyle\int_{0}^{8} \dfrac{x}{\sqrt{x + 1}}\,\mathrm{d}x$$ksql$, 3, $ksql$$\left(\tfrac{2}{3} \cdot 27 - 6\right) - \left(\tfrac{2}{3} - 2\right) = 12 - \left(-\tfrac{4}{3}\right) = \dfrac{40}{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 2} = g$: $\displaystyle\int_{2}^{7} x\sqrt{x + 2}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Stel $\sqrt{x + 2} = g$, want onder de wortel staat $x$ plus een getal en ervóór staat een losse $x$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 2} = g$: $\displaystyle\int_{2}^{7} x\sqrt{x + 2}\,\mathrm{d}x$$ksql$, 1, $ksql$$x = g^{2} - 2$ en $\mathrm{d}x = 2g\,\mathrm{d}g$. Bij $x = 2$ hoort $g = 2$, bij $x = 7$ hoort $g = 3$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 2} = g$: $\displaystyle\int_{2}^{7} x\sqrt{x + 2}\,\mathrm{d}x$$ksql$, 2, $ksql$De integraal wordt $\int_{2}^{3} (g^{2} - 2) \cdot g \cdot 2g\,\mathrm{d}g = \int_{2}^{3} (2g^{4} - 4g^{2})\,\mathrm{d}g = \left[\tfrac{2}{5}g^{5} - \tfrac{4}{3}g^{3}\right]_{2}^{3}$.$ksql$),
  ('k1b_bepaald', 'k1b_wortelsubstitutie', $ksql$Bereken exact met de substitutie $\sqrt{x + 2} = g$: $\displaystyle\int_{2}^{7} x\sqrt{x + 2}\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $g = 3$: $\tfrac{486}{5} - 36 = \tfrac{306}{5}$. Bij $g = 2$: $\tfrac{64}{5} - \tfrac{32}{3} = \tfrac{32}{15}$. Verschil: $\tfrac{306}{5} - \tfrac{32}{15} = \dfrac{886}{15}$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1: op $[1, \mathrm{e}]$ is $\ln(x) \ge 0$, dus de grafiek ligt op of boven de $x$-as. De oppervlakte is $\displaystyle\int_{1}^{\mathrm{e}} \dfrac{4\ln(x)}{x}\,\mathrm{d}x$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Kern $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$. Dan is $\dfrac{1}{x}\,\mathrm{d}x = \mathrm{d}g$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$$\int 4g\,\mathrm{d}g = 2g^{2} = 2\ln^{2}(x)$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4\ln(x)}{x}$, de $x$-as en de lijn $x = \mathrm{e}$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[2\ln^{2}(x)\right]_{1}^{\mathrm{e}} = 2 \cdot 1 - 2 \cdot 0 = 2$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(5)$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1: voor $x \ge 0$ ligt de grafiek op of boven de $x$-as, dus de oppervlakte is $\displaystyle\int_{0}^{p} \dfrac{2x}{x^{2} + 4}\,\mathrm{d}x$ en die moet $\ln(5)$ worden.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(5)$. Bereken exact $p$.$ksql$, 1, $ksql$Kern $g(x) = x^{2} + 4$, dus $g'(x) = 2x$. De teller is precies $g'(x)$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(5)$. Bereken exact $p$.$ksql$, 2, $ksql$Een primitieve is $\ln(x^{2} + 4)$. Grenzen: $\ln(p^{2} + 4) - \ln(4) = \ln\left(\dfrac{p^{2} + 4}{4}\right)$.$ksql$),
  ('k1b_toepassingen', 'k1b_opp_p', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 4}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(5)$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: $\dfrac{p^{2} + 4}{4} = 5$, dus $p^{2} + 4 = 20$ en $p^{2} = 16$. Omdat $p > 0$ is $p = 4$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(3x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm maal een sinus. Partieel integreren: de sinus primitiveren, de veelterm differentiëren.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(3x)$$ksql$, 1, $ksql$Kies $h'(x) = \sin(3x)$, dus $h(x) = -\tfrac{1}{3}\cos(3x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(3x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $-\tfrac{1}{3}x\cos(3x) - \int -\tfrac{1}{3}\cos(3x)\,\mathrm{d}x = -\tfrac{1}{3}x\cos(3x) + \tfrac{1}{3} \cdot \tfrac{1}{3}\sin(3x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = x\sin(3x)$$ksql$, 3, $ksql$$F(x) = -\tfrac{1}{3}x\cos(3x) + \tfrac{1}{9}\sin(3x) + c$. Controle: differentiëren geeft $-\tfrac{1}{3}\cos(3x) + x\sin(3x) + \tfrac{1}{3}\cos(3x) = x\sin(3x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (3x + 2)\cos(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een lineaire veelterm maal een cosinus. Partieel integreren.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (3x + 2)\cos(2x)$$ksql$, 1, $ksql$Kies $h'(x) = \cos(2x)$, dus $h(x) = \tfrac{1}{2}\sin(2x)$, en $g(x) = 3x + 2$, dus $g'(x) = 3$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (3x + 2)\cos(2x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\tfrac{1}{2}(3x + 2)\sin(2x) - \int \tfrac{3}{2}\sin(2x)\,\mathrm{d}x$. En $\int \sin(2x)\,\mathrm{d}x = -\tfrac{1}{2}\cos(2x)$, dus het minteken ervoor wordt $+\tfrac{3}{4}\cos(2x)$.$ksql$),
  ('k2a_partieel', 'k2a_macht_gonio', $ksql$Primitiveer: $f(x) = (3x + 2)\cos(2x)$$ksql$, 3, $ksql$$F(x) = \tfrac{1}{2}(3x + 2)\sin(2x) + \tfrac{3}{4}\cos(2x) + c$. Controle: differentieer en de productregel plus de kettingregel geven $(3x + 2)\cos(2x)$ terug.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{4x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm maal een e-macht. Partieel integreren: de e-macht primitiveren, de veelterm differentiëren.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{4x}$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{4x}$, dus $h(x) = \tfrac{1}{4}\mathrm{e}^{4x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{4x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\tfrac{1}{4}x\mathrm{e}^{4x} - \int \tfrac{1}{4}\mathrm{e}^{4x}\,\mathrm{d}x = \tfrac{1}{4}x\mathrm{e}^{4x} - \tfrac{1}{16}\mathrm{e}^{4x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = x\mathrm{e}^{4x}$$ksql$, 3, $ksql$$F(x) = \tfrac{1}{16}(4x - 1)\mathrm{e}^{4x} + c$. Controle: differentiëren geeft $\tfrac{1}{16} \cdot 4\mathrm{e}^{4x} + \tfrac{1}{16}(4x - 1) \cdot 4\mathrm{e}^{4x} = x\mathrm{e}^{4x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x - 3)\mathrm{e}^{-x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een lineaire veelterm maal een e-macht met een min in de exponent.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x - 3)\mathrm{e}^{-x}$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = 2x - 3$, dus $g'(x) = 2$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x - 3)\mathrm{e}^{-x}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $-(2x - 3)\mathrm{e}^{-x} - \int -2\mathrm{e}^{-x}\,\mathrm{d}x = -(2x - 3)\mathrm{e}^{-x} - 2\mathrm{e}^{-x} = (1 - 2x)\mathrm{e}^{-x}$.$ksql$),
  ('k2a_partieel', 'k2a_macht_e', $ksql$Primitiveer: $f(x) = (2x - 3)\mathrm{e}^{-x}$$ksql$, 3, $ksql$$F(x) = (1 - 2x)\mathrm{e}^{-x} + c$. Controle: differentiëren geeft $-2\mathrm{e}^{-x} + (1 - 2x)(-\mathrm{e}^{-x}) = (2x - 3)\mathrm{e}^{-x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{3}\ln(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een product met $\ln$. Differentiëer de $\ln$ en primitiveer de macht van $x$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{3}\ln(x)$$ksql$, 1, $ksql$Kies $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$, en $h'(x) = x^{3}$, dus $h(x) = \tfrac{1}{4}x^{4}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{3}\ln(x)$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $\tfrac{1}{4}x^{4}\ln(x) - \int \tfrac{1}{4}x^{3}\,\mathrm{d}x = \tfrac{1}{4}x^{4}\ln(x) - \tfrac{1}{16}x^{4}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = x^{3}\ln(x)$$ksql$, 3, $ksql$$F(x) = \tfrac{1}{4}x^{4}\ln(x) - \tfrac{1}{16}x^{4} + c$. Controle: differentiëren geeft $x^{3}\ln(x) + \tfrac{1}{4}x^{3} - \tfrac{1}{4}x^{3} = x^{3}\ln(x)$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{2}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: $\ln$ gedeeld door een macht van $x$. Differentiëer de $\ln$ en primitiveer de macht.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{2}}$$ksql$, 1, $ksql$Kies $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$, en $h'(x) = x^{-2}$, dus $h(x) = -x^{-1} = -\dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{2}}$$ksql$, 2, $ksql$Vul de regel in: $\int g(x) \cdot h'(x)\,\mathrm{d}x = g(x) \cdot h(x) - \int h(x) \cdot g'(x)\,\mathrm{d}x$. Dat geeft $-\dfrac{\ln(x)}{x} - \int -\dfrac{1}{x} \cdot \dfrac{1}{x}\,\mathrm{d}x = -\dfrac{\ln(x)}{x} - \dfrac{1}{x}$.$ksql$),
  ('k2a_partieel', 'k2a_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln(x)}{x^{2}}$$ksql$, 3, $ksql$$F(x) = -\dfrac{\ln(x) + 1}{x} + c$. Controle: differentieer met de quotiëntregel en je krijgt $\dfrac{\ln(x)}{x^{2}}$ terug.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} x\sin(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. Eerst partieel integreren, daarna de grenzen.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} x\sin(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} x\sin(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $-x\cos(x) - \int -\cos(x)\,\mathrm{d}x = -x\cos(x) + \sin(x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{3}\pi} x\sin(x)\,\mathrm{d}x$$ksql$, 3, $ksql$$\left[-x\cos(x) + \sin(x)\right]_{0}^{\frac{1}{3}\pi} = -\tfrac{1}{3}\pi \cdot \tfrac{1}{2} + \tfrac{1}{2}\sqrt{3} = \dfrac{\sqrt{3}}{2} - \dfrac{1}{6}\pi$. Bij $x = 0$ is de primitieve $0$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal met een sinus van $2x$. Eerst partieel integreren.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \sin(2x)$, dus $h(x) = -\tfrac{1}{2}\cos(2x)$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $-\tfrac{1}{2}x\cos(2x) - \int -\tfrac{1}{2}\cos(2x)\,\mathrm{d}x = -\tfrac{1}{2}x\cos(2x) + \tfrac{1}{4}\sin(2x)$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_gonio', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{4}\pi} x\sin(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = \tfrac{1}{4}\pi$ is $\cos\left(\tfrac{1}{2}\pi\right) = 0$ en $\sin\left(\tfrac{1}{2}\pi\right) = 1$, dus de primitieve is $\tfrac{1}{4}$. Bij $x = 0$ is hij $0$. Het antwoord is $\tfrac{1}{4}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. Een veelterm maal een e-macht: partieel integreren.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $\tfrac{1}{2}x\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x\mathrm{e}^{2x}\,\mathrm{d}x$$ksql$, 3, $ksql$$\left[\tfrac{1}{2}x\mathrm{e}^{2x} - \tfrac{1}{4}\mathrm{e}^{2x}\right]_{0}^{1} = \left(\tfrac{1}{2}\mathrm{e}^{2} - \tfrac{1}{4}\mathrm{e}^{2}\right) - \left(-\tfrac{1}{4}\right) = \dfrac{\mathrm{e}^{2} + 1}{4}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x^{2}\ln(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal met een $\ln$. Differentiëer de $\ln$ en primitiveer $x^{2}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x^{2}\ln(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Kies $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$, en $h'(x) = x^{2}$, dus $h(x) = \tfrac{1}{3}x^{3}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x^{2}\ln(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Een primitieve is $\tfrac{1}{3}x^{3}\ln(x) - \int \tfrac{1}{3}x^{2}\,\mathrm{d}x = \tfrac{1}{3}x^{3}\ln(x) - \tfrac{1}{9}x^{3}$.$ksql$),
  ('k2a_bepaald', 'k2a_bepaald_e_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x^{2}\ln(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = \mathrm{e}$: $\tfrac{1}{3}\mathrm{e}^{3} - \tfrac{1}{9}\mathrm{e}^{3} = \tfrac{2}{9}\mathrm{e}^{3}$. Bij $x = 1$: $-\tfrac{1}{9}$. Verschil: $\dfrac{2\mathrm{e}^{3} + 1}{9}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1: op $[0, 1]$ ligt de grafiek op of boven de $x$-as (hij raakt de as bij $x = 0$). De oppervlakte is $\displaystyle\int_{0}^{1} x\mathrm{e}^{-x}\,\mathrm{d}x$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Partieel integreren: $h'(x) = \mathrm{e}^{-x}$, dus $h(x) = -\mathrm{e}^{-x}$, en $g(x) = x$, dus $g'(x) = 1$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $-x\mathrm{e}^{-x} - \int -\mathrm{e}^{-x}\,\mathrm{d}x = -(x + 1)\mathrm{e}^{-x}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[-(x + 1)\mathrm{e}^{-x}\right]_{0}^{1} = -\dfrac{2}{\mathrm{e}} - (-1) = 1 - \dfrac{2}{\mathrm{e}}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $1 - \dfrac{3}{\mathrm{e}^{2}}$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1: voor $x \ge 0$ ligt de grafiek op of boven de $x$-as, dus de oppervlakte is $\displaystyle\int_{0}^{p} x\mathrm{e}^{-x}\,\mathrm{d}x$ en die moet $1 - \dfrac{3}{\mathrm{e}^{2}}$ worden.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $1 - \dfrac{3}{\mathrm{e}^{2}}$. Bereken exact $p$.$ksql$, 1, $ksql$Zoals bij de oppervlakte tot $x = 1$: een primitieve is $-(x + 1)\mathrm{e}^{-x}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $1 - \dfrac{3}{\mathrm{e}^{2}}$. Bereken exact $p$.$ksql$, 2, $ksql$Grenzen: $\big[-(x + 1)\mathrm{e}^{-x}\big]_{0}^{p} = 1 - (p + 1)\mathrm{e}^{-p}$.$ksql$),
  ('k2a_toepassingen', 'k2a_opp', $ksql$De grafiek van $f(x) = x\mathrm{e}^{-x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $1 - \dfrac{3}{\mathrm{e}^{2}}$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: $1 - (p + 1)\mathrm{e}^{-p} = 1 - \dfrac{3}{\mathrm{e}^{2}}$, dus $(p + 1)\mathrm{e}^{-p} = 3\mathrm{e}^{-2}$. Voor $p = 2$ klopt dat: $3\mathrm{e}^{-2} = 3\mathrm{e}^{-2}$. Dus $p = 2$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(2x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een cosinus. Differentiëren haalt de graad één omlaag, dus je partieel integreert twee keer.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(2x)$$ksql$, 1, $ksql$Eerste ronde: $h'(x) = \cos(2x)$, dus $h(x) = \tfrac{1}{2}\sin(2x)$, en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(2x)$$ksql$, 2, $ksql$Dat geeft $\tfrac{1}{2}x^{2}\sin(2x) - \int x\sin(2x)\,\mathrm{d}x$. Tweede ronde op $\int x\sin(2x)\,\mathrm{d}x$: $h(x) = -\tfrac{1}{2}\cos(2x)$ en $g(x) = x$, dus $-\tfrac{1}{2}x\cos(2x) + \tfrac{1}{4}\sin(2x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = x^{2}\cos(2x)$$ksql$, 3, $ksql$Trek die primitieve af: $F(x) = \tfrac{1}{2}x^{2}\sin(2x) + \tfrac{1}{2}x\cos(2x) - \tfrac{1}{4}\sin(2x) + c$. Controle: differentiëren geeft $x^{2}\cos(2x)$ terug.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = (x^{2} + x)\sin(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een sinus. Twee rondes partieel integreren.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = (x^{2} + x)\sin(x)$$ksql$, 1, $ksql$Eerste ronde: $h'(x) = \sin(x)$, dus $h(x) = -\cos(x)$, en $g(x) = x^{2} + x$, dus $g'(x) = 2x + 1$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = (x^{2} + x)\sin(x)$$ksql$, 2, $ksql$Dat geeft $-(x^{2} + x)\cos(x) + \int (2x + 1)\cos(x)\,\mathrm{d}x$. Tweede ronde: $h(x) = \sin(x)$ en $g(x) = 2x + 1$, dus $(2x + 1)\sin(x) - \int 2\sin(x)\,\mathrm{d}x = (2x + 1)\sin(x) + 2\cos(x)$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_gonio', $ksql$Primitiveer: $f(x) = (x^{2} + x)\sin(x)$$ksql$, 3, $ksql$$F(x) = -(x^{2} + x)\cos(x) + (2x + 1)\sin(x) + 2\cos(x) + c$. Controle: de termen met $\cos$ en de losse $\sin$ vallen tegen elkaar weg en je houdt $(x^{2} + x)\sin(x)$ over.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{3x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht. Twee rondes: de e-macht blijft, de veelterm zakt per ronde één graad.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{3x}$$ksql$, 1, $ksql$Eerste ronde: $h'(x) = \mathrm{e}^{3x}$, dus $h(x) = \tfrac{1}{3}\mathrm{e}^{3x}$, en $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{3x}$$ksql$, 2, $ksql$Dat geeft $\tfrac{1}{3}x^{2}\mathrm{e}^{3x} - \tfrac{2}{3}\int x\mathrm{e}^{3x}\,\mathrm{d}x$. Tweede ronde: $\int x\mathrm{e}^{3x}\,\mathrm{d}x = \tfrac{1}{3}x\mathrm{e}^{3x} - \tfrac{1}{9}\mathrm{e}^{3x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = x^{2}\mathrm{e}^{3x}$$ksql$, 3, $ksql$Invullen en gelijknamig maken: $F(x) = \dfrac{9x^{2} - 6x + 2}{27}\,\mathrm{e}^{3x} + c$. Controle: differentiëren geeft $x^{2}\mathrm{e}^{3x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = (x^{2} - 2)\mathrm{e}^{-2x}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een veelterm van graad 2 maal een e-macht met een min in de exponent. Twee rondes.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = (x^{2} - 2)\mathrm{e}^{-2x}$$ksql$, 1, $ksql$Eerste ronde: $h'(x) = \mathrm{e}^{-2x}$, dus $h(x) = -\tfrac{1}{2}\mathrm{e}^{-2x}$, en $g(x) = x^{2} - 2$, dus $g'(x) = 2x$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = (x^{2} - 2)\mathrm{e}^{-2x}$$ksql$, 2, $ksql$Dat geeft $-\tfrac{1}{2}(x^{2} - 2)\mathrm{e}^{-2x} + \int x\mathrm{e}^{-2x}\,\mathrm{d}x$. Tweede ronde: $\int x\mathrm{e}^{-2x}\,\mathrm{d}x = -\tfrac{1}{2}x\mathrm{e}^{-2x} - \tfrac{1}{4}\mathrm{e}^{-2x}$.$ksql$),
  ('k2b_herhaald', 'k2b_kwadraat_e', $ksql$Primitiveer: $f(x) = (x^{2} - 2)\mathrm{e}^{-2x}$$ksql$, 3, $ksql$Bij elkaar: $F(x) = -\dfrac{2x^{2} + 2x - 3}{4}\,\mathrm{e}^{-2x} + c$. Controle: differentiëren geeft $(x^{2} - 2)\mathrm{e}^{-2x}$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\cos(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een cosinus. Geen van beide wordt eenvoudiger, dus na twee rondes komt de integraal terug. Noem hem $I$ en los hem op.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\cos(x)$$ksql$, 1, $ksql$Eerste ronde: $h'(x) = \mathrm{e}^{2x}$, dus $h(x) = \tfrac{1}{2}\mathrm{e}^{2x}$, en $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$. Dan is $I = \tfrac{1}{2}\mathrm{e}^{2x}\cos(x) + \tfrac{1}{2}\int \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\cos(x)$$ksql$, 2, $ksql$Tweede ronde op $\int \mathrm{e}^{2x}\sin(x)\,\mathrm{d}x$: weer de e-macht primitiveren. Na uitwerken staat $I$ rechts ook, met een factor $\tfrac{1}{4}$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{2x}\cos(x)$$ksql$, 3, $ksql$Alles met $I$ naar links: $I - \tfrac{1}{4}I = \tfrac{1}{2}\mathrm{e}^{2x}\cos(x) + \tfrac{1}{4}\mathrm{e}^{2x}\sin(x)$. Dus $I = \tfrac{1}{5}\mathrm{e}^{2x}\big(2\cos(x) + \sin(x)\big)$. Antwoord: $F(x) = \tfrac{1}{5}\mathrm{e}^{2x}\big(2\cos(x) + \sin(x)\big) + c$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-2x}\cos(3x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht maal een cosinus, allebei met een factor in het argument. Twee rondes, daarna de integraal naar links halen.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-2x}\cos(3x)$$ksql$, 1, $ksql$Noem de integraal $I$. Kies $h'(x) = \mathrm{e}^{-2x}$, dus $h(x) = -\tfrac{1}{2}\mathrm{e}^{-2x}$, en $g(x) = \cos(3x)$, dus $g'(x) = -3\sin(3x)$.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-2x}\cos(3x)$$ksql$, 2, $ksql$Na de eerste ronde staat er een integraal met $\sin(3x)$. Die doe je op dezelfde manier nog een keer. Dan komt $I$ terug met factor $\dfrac{9}{4}$, want elke ronde brengt een factor vanuit de afgeleide van de cosinus of sinus.$ksql$),
  ('k2b_herhaald', 'k2b_terugkomen', $ksql$Primitiveer: $f(x) = \mathrm{e}^{-2x}\cos(3x)$$ksql$, 3, $ksql$De noemer wordt $4 + 9 = 13$. $F(x) = \dfrac{\mathrm{e}^{-2x}\big(-2\cos(3x) + 3\sin(3x)\big)}{13} + c$. Controle: differentiëren geeft $\mathrm{e}^{-2x}\cos(3x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{3x}\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. Eerst twee rondes partieel integreren, daarna de grenzen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{3x}\,\mathrm{d}x$$ksql$, 1, $ksql$De primitieve van $x^{2}\mathrm{e}^{3x}$ is $\dfrac{9x^{2} - 6x + 2}{27}\,\mathrm{e}^{3x}$, zoals bij het primitiveren van deze vorm.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{3x}\,\mathrm{d}x$$ksql$, 2, $ksql$Bij $x = 1$: $\dfrac{9 - 6 + 2}{27}\mathrm{e}^{3} = \dfrac{5\mathrm{e}^{3}}{27}$. Bij $x = 0$: $\dfrac{2}{27}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{1} x^{2}\mathrm{e}^{3x}\,\mathrm{d}x$$ksql$, 3, $ksql$Verschil: $\dfrac{5\mathrm{e}^{3} - 2}{27}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(2x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. De primitieve heb je nodig van $x^{2}cos(2x)$, via twee rondes partieel integreren.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(2x)\,\mathrm{d}x$$ksql$, 1, $ksql$Een primitieve is $\tfrac{1}{2}x^{2}\sin(2x) + \tfrac{1}{2}x\cos(2x) - \tfrac{1}{4}\sin(2x)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(2x)\,\mathrm{d}x$$ksql$, 2, $ksql$Bij $x = \tfrac{1}{2}\pi$ is $\sin(\pi) = 0$ en $\cos(\pi) = -1$, dus de primitieve is $\tfrac{1}{2} \cdot \tfrac{1}{2}\pi \cdot (-1) = -\tfrac{1}{4}\pi$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_kwadraat', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} x^{2}\cos(2x)\,\mathrm{d}x$$ksql$, 3, $ksql$Bij $x = 0$ is de primitieve $0$. Het antwoord is $-\dfrac{1}{4}\pi$. Het mag negatief zijn: dit is een integraal, geen oppervlakte, en $\cos(2x)$ is op het rechterdeel van het interval negatief.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal waarbij de integraal terugkomt. Eerst de primitieve, daarna de grenzen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Twee rondes partieel integreren en $I$ naar links halen geeft primitieve $\tfrac{1}{5}\mathrm{e}^{2x}\big(2\cos(x) + \sin(x)\big)$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Bij $x = \tfrac{1}{2}\pi$: $\tfrac{1}{5}\mathrm{e}^{\pi}\big(0 + 1\big) = \tfrac{1}{5}\mathrm{e}^{\pi}$. Bij $x = 0$: $\tfrac{1}{5} \cdot 2 = \tfrac{2}{5}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{2x}\cos(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Verschil: $\dfrac{\mathrm{e}^{\pi} - 2}{5}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{-2x}\cos(3x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. Eerst de primitieve van $\mathrm{e}^{-2x}\cos(3x)$ via twee rondes, daarna de grenzen.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{-2x}\cos(3x)\,\mathrm{d}x$$ksql$, 1, $ksql$Een primitieve is $\dfrac{\mathrm{e}^{-2x}\big(-2\cos(3x) + 3\sin(3x)\big)}{13}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{-2x}\cos(3x)\,\mathrm{d}x$$ksql$, 2, $ksql$Bij $x = \tfrac{1}{2}\pi$: $\cos\left(\tfrac{3}{2}\pi\right) = 0$ en $\sin\left(\tfrac{3}{2}\pi\right) = -1$, dus $\dfrac{\mathrm{e}^{-\pi} \cdot (-3)}{13} = -\dfrac{3\mathrm{e}^{-\pi}}{13}$. Bij $x = 0$: $\dfrac{-2}{13}$.$ksql$),
  ('k2b_bepaald', 'k2b_bepaald_terugkomen', $ksql$Bereken exact: $\displaystyle\int_{0}^{\frac{1}{2}\pi} \mathrm{e}^{-2x}\cos(3x)\,\mathrm{d}x$$ksql$, 3, $ksql$Verschil: $-\dfrac{3\mathrm{e}^{-\pi}}{13} - \left(-\dfrac{2}{13}\right) = \dfrac{2 - 3\mathrm{e}^{-\pi}}{13}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x^{2} + 1)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1: op $[0, 1]$ ligt de grafiek boven de $x$-as. De oppervlakte is $\displaystyle\int_{0}^{1} (x^{2} + 1)\mathrm{e}^{x}\,\mathrm{d}x$. Bij $x = 0$ begint het vlakdeel aan de $y$-as.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x^{2} + 1)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Twee rondes partieel integreren. $\int x^{2}\mathrm{e}^{x}\,\mathrm{d}x = (x^{2} - 2x + 2)\mathrm{e}^{x}$ en $\int \mathrm{e}^{x}\,\mathrm{d}x = \mathrm{e}^{x}$, samen $(x^{2} - 2x + 3)\mathrm{e}^{x}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x^{2} + 1)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Controle van die primitieve: de afgeleide is $(2x - 2)\mathrm{e}^{x} + (x^{2} - 2x + 3)\mathrm{e}^{x} = (x^{2} + 1)\mathrm{e}^{x}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = (x^{2} + 1)\mathrm{e}^{x}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[(x^{2} - 2x + 3)\mathrm{e}^{x}\right]_{0}^{1} = 2\mathrm{e} - 3$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = x^{2}\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $2\mathrm{e}^{2} - 2$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1: voor $x \ge 0$ ligt de grafiek op of boven de $x$-as, dus de oppervlakte is $\displaystyle\int_{0}^{p} x^{2}\mathrm{e}^{x}\,\mathrm{d}x$ en die moet $2\mathrm{e}^{2} - 2$ worden.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = x^{2}\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $2\mathrm{e}^{2} - 2$. Bereken exact $p$.$ksql$, 1, $ksql$Twee rondes partieel integreren geven primitieve $(x^{2} - 2x + 2)\mathrm{e}^{x}$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = x^{2}\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $2\mathrm{e}^{2} - 2$. Bereken exact $p$.$ksql$, 2, $ksql$Grenzen: $\big[(x^{2} - 2x + 2)\mathrm{e}^{x}\big]_{0}^{p} = (p^{2} - 2p + 2)\mathrm{e}^{p} - 2$.$ksql$),
  ('k2b_toepassingen', 'k2b_opp', $ksql$De grafiek van $f(x) = x^{2}\mathrm{e}^{x}$, de $x$-as en de lijn $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $2\mathrm{e}^{2} - 2$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: $(p^{2} - 2p + 2)\mathrm{e}^{p} - 2 = 2\mathrm{e}^{2} - 2$, dus $(p^{2} - 2p + 2)\mathrm{e}^{p} = 2\mathrm{e}^{2}$. Voor $p = 2$ staat er $2\mathrm{e}^{2} = 2\mathrm{e}^{2}$. Dus $p = 2$.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = 2\ln^{2}(x)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kwadraat van $\ln$. Partieel integreren, en daarna nog een keer, want er blijft een $\ln$ over.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = 2\ln^{2}(x)$$ksql$, 1, $ksql$Kies $g(x) = \ln^{2}(x)$, dus $g'(x) = \dfrac{2\ln(x)}{x}$, en $h'(x) = 2$, dus $h(x) = 2x$.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = 2\ln^{2}(x)$$ksql$, 2, $ksql$Dat geeft $2x\ln^{2}(x) - \int 4\ln(x)\,\mathrm{d}x$. En $\int \ln(x)\,\mathrm{d}x = x\ln(x) - x$, dus $\int 4\ln(x)\,\mathrm{d}x = 4x\ln(x) - 4x$.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = 2\ln^{2}(x)$$ksql$, 3, $ksql$$F(x) = 2x\ln^{2}(x) - 4x\ln(x) + 4x + c$. Controle: differentiëren geeft $2\ln^{2}(x) + 4\ln(x) - 4\ln(x) - 4 + 4 = 2\ln^{2}(x)$.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln^{2}(x)}{x^{3}}$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kwadraat van $\ln$ gedeeld door een macht van $x$. Differentiëer de $\ln$ en primitiveer de macht. Er zijn twee rondes nodig.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln^{2}(x)}{x^{3}}$$ksql$, 1, $ksql$Eerste ronde: $g(x) = \ln^{2}(x)$, dus $g'(x) = \dfrac{2\ln(x)}{x}$, en $h'(x) = x^{-3}$, dus $h(x) = -\dfrac{1}{2x^{2}}$.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln^{2}(x)}{x^{3}}$$ksql$, 2, $ksql$Dat geeft $-\dfrac{\ln^{2}(x)}{2x^{2}} + \int \dfrac{\ln(x)}{x^{3}}\,\mathrm{d}x$. Tweede ronde op die nieuwe integraal: $-\dfrac{\ln(x)}{2x^{2}} - \dfrac{1}{4x^{2}}$.$ksql$),
  ('k2b_logaritme', 'k2b_ln', $ksql$Primitiveer: $f(x) = \dfrac{\ln^{2}(x)}{x^{3}}$$ksql$, 3, $ksql$Bij elkaar: $F(x) = -\dfrac{2\ln^{2}(x) + 2\ln(x) + 1}{4x^{2}} + c$. Controle: differentiëren geeft $\dfrac{\ln^{2}(x)}{x^{3}}$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x\ln^{2}(x)\,\mathrm{d}x$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Bepaalde integraal. Differentiëer $\ln^{2}(x)$ en primitiveer $x$; daarna blijft er nog een $\ln$ over.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x\ln^{2}(x)\,\mathrm{d}x$$ksql$, 1, $ksql$Een primitieve is $\tfrac{1}{2}x^{2}\ln^{2}(x) - \tfrac{1}{2}x^{2}\ln(x) + \tfrac{1}{4}x^{2}$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x\ln^{2}(x)\,\mathrm{d}x$$ksql$, 2, $ksql$Bij $x = \mathrm{e}$: $\tfrac{1}{2}\mathrm{e}^{2} - \tfrac{1}{2}\mathrm{e}^{2} + \tfrac{1}{4}\mathrm{e}^{2} = \tfrac{1}{4}\mathrm{e}^{2}$. Bij $x = 1$: $\tfrac{1}{4}$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Bereken exact: $\displaystyle\int_{1}^{\mathrm{e}} x\ln^{2}(x)\,\mathrm{d}x$$ksql$, 3, $ksql$Verschil: $\dfrac{\mathrm{e}^{2} - 1}{4}$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln^{2}(x)$, de $x$-as en de lijn $x = \mathrm{e}^{3}$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1: $\ln^{2}(x)$ ligt op $[1, \mathrm{e}^{3}]$ op of boven de $x$-as. De oppervlakte is $\displaystyle\int_{1}^{\mathrm{e}^{3}} \ln^{2}(x)\,\mathrm{d}x$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln^{2}(x)$, de $x$-as en de lijn $x = \mathrm{e}^{3}$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$Twee rondes partieel integreren geven primitieve $x\ln^{2}(x) - 2x\ln(x) + 2x$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln^{2}(x)$, de $x$-as en de lijn $x = \mathrm{e}^{3}$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Bij $x = \mathrm{e}^{3}$: $\mathrm{e}^{3} \cdot 9 - 2\mathrm{e}^{3} \cdot 3 + 2\mathrm{e}^{3} = 5\mathrm{e}^{3}$. Bij $x = 1$: $2$.$ksql$),
  ('k2b_logaritme', 'k2b_bepaald_ln', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \ln^{2}(x)$, de $x$-as en de lijn $x = \mathrm{e}^{3}$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Verschil: $5\mathrm{e}^{3} - 2$. Dat is de oppervlakte.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k0b_machten_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k0b_standaardprimitieven' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k0b_machten_gonio hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k0b_exponenten' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k0b_standaardprimitieven' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k0b_exponenten hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k0b_logaritmen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k0b_standaardprimitieven' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k0b_logaritmen hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k0b_lin_e_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k0b_lineaire_kern' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k0b_lin_e_gonio hoort 8 vragen te hebben, gevonden %', n; END IF;
